// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes32 role, address sender, address actor) public {
        bytes32 proposer = keccak256("PROPOSER_ROLE");
        bytes32 executor = keccak256("EXECUTOR_ROLE");
        vm.assume(role == proposer || role == executor);
        vm.assume(sender != actor);
        vm.assume(actor != address(0));

        // the deployer (this test contract) holds TIMELOCK_ADMIN_ROLE, so it can grant
        c.grantRole(role, actor);
        assertTrue(c.hasRole(role, actor));

        vm.prank(sender);
        bool ok;
        try c.renounceRole(role, actor) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a renounceRole call that did NOT succeed must leave membership intact.
        assertTrue(!ok || c.hasRole(role, actor));
    }
}
